namespace {

void expect(bool condition, const std::string& message) {
  if (!condition)
    throw std::runtime_error(message);
}

// Dynamic WLED blending is call-dependent, so the response must expose both
// exact lookup tables while every fixed policy needs only its one active table.
void blend_policy_selects_complete_lookup_set() {
  PaletteSerialDumpPlan dynamic = makePaletteSerialDumpPlan(0, 0);
  expect(dynamic.lookupCount == 2,
      "dynamic blend policy did not expose both lookup variants");
  expect(dynamic.lookupModes[0] == PaletteLookupLinearWrap
          && dynamic.lookupModes[1] == PaletteLookupLinearNoWrap,
      "dynamic blend policy exposed the wrong lookup variants");

  const std::array<std::pair<uint8_t, PaletteSerialLookupMode>, 3> fixedPolicies = {{
      {1, PaletteLookupLinearWrap},
      {2, PaletteLookupLinearNoWrap},
      {3, PaletteLookupNoBlend},
  }};
  for (const auto& policy : fixedPolicies) {
    PaletteSerialDumpPlan plan = makePaletteSerialDumpPlan(0, policy.first);
    expect(plan.lookupCount == 1, "fixed blend policy exposed multiple lookup tables");
    expect(plan.lookupModes[0] == policy.second,
        "fixed blend policy exposed the wrong lookup table");
  }
}

// Source-stop framing derives its record count from the declared stop count.
// Counts beyond both 16 slots and today's 18-stop storage remain representable.
void source_stop_framing_is_variable_length() {
  PaletteSerialDumpPlan eighteenStops = makePaletteSerialDumpPlan(18, 3);
  PaletteSerialDumpPlan thirtyThreeStops = makePaletteSerialDumpPlan(33, 3);

  expect(eighteenStops.stopChunks == 5,
      "18 source stops did not span the expected bounded records");
  expect(thirtyThreeStops.stopChunks == 9,
      "serial framing imposed the firmware's current stop-storage limit");
  expect(thirtyThreeStops.dataParts - eighteenStops.dataParts == 4,
      "additional source stops did not increase the self-described record count");
}

// Every lookup table covers all 256 eight-bit indices in bounded eight-sample
// records, and slots/source records add to the declared data-part total.
void data_part_count_matches_declared_representations() {
  PaletteSerialDumpPlan plan = makePaletteSerialDumpPlan(18, 0);
  expect(plan.slotChunks == 2, "runtime slots were not completely framed");
  expect(plan.lookupChunks == 32, "lookup table did not cover all 256 indices");
  expect(plan.dataParts == 2 + 5 + 2 * 32,
      "declared data-part count omitted a palette representation");

  PaletteSerialDumpPlan invalid = makePaletteSerialDumpPlan(18, 4);
  expect(invalid.lookupCount == 0,
      "unsupported blend policy silently selected a lookup representation");
}

} // namespace

int main() {
  const std::array<std::pair<const char*, void (*)()>, 3> tests = {{
      {"blend policy selects complete lookup set", blend_policy_selects_complete_lookup_set},
      {"source-stop framing is variable length", source_stop_framing_is_variable_length},
      {"data-part count matches declared representations", data_part_count_matches_declared_representations},
  }};

  for (const auto& test : tests) {
    try {
      test.second();
      std::cout << "PASS: " << test.first << '\n';
    } catch (const std::exception& error) {
      std::cerr << "FAIL: " << test.first << ": " << error.what() << '\n';
      return 1;
    }
  }
  return 0;
}
